function countLonelyValues(a: number[], b: number[], d: number): number {
  let count = 0;
  for (const x of a) {
    let lonely = true;
    for (const y of b) {
      if (Math.abs(x - y) <= d) { lonely = false; break; }
    }
    if (lonely) count++;
  }
  return count;
}

