function countLonelyValues(a: number[], b: number[], d: number): number {
  const s = [...b].sort((x, y) => x - y);
  const m = s.length;
  let count = 0;
  for (const x of a) {
    let lo = 0, hi = m; // first index with s[idx] >= x
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (s[mid] < x) lo = mid + 1; else hi = mid;
    }
    const closeAbove = lo < m && s[lo] - x <= d;
    const closeBelow = lo > 0 && x - s[lo - 1] <= d;
    if (!closeAbove && !closeBelow) count++;
  }
  return count;
}

